mapper.insert:
insert into PBC_PROD_RAISING_SUB () select HIS_NO, RAISING_DATE, PBC_PROD_ID, BUY_PLACE, CUSTOMER_TYPE1, CCY, RAISING_AMTSUM, RAISING_AMTSUM_CNY, RAISING_QTY, REDAMT, REDAMT_CNY, REDQTY, ENDAMTSUM, ENDAMTSUM_CNY, ENDQTY, PROD_VALUE, PROD_VALUE_CNY, UNIT_VALUE_TOTAL, UNIT_VALUE_TOTAL_CNY, PROD_HIGH_YIELD, PROD_LOW_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, sysdate, UPDATE_USER, sysdate from ( select , rank() over (partition by PBC_PROD_ID order by nvl(update_time,create_time) desc) ranknum from PBC_PROD_RAISING_SUB_HIS
select #{item.pbcProdId,jdbcType=CHAR}, #{item.raisingDate,jdbcType=CHAR} from sysibm.SYSDUMMY1
) where ranknum = 1

mapper.delete:
	delete from PBC_PROD_RAISING_SUB_HIS
	where PBC_PROD_ID in (
	    select  PBC_PROD_ID
	      from (
	      	select PBC_PROD_ID ,
	      	rank() over (partition by PBC_PROD_ID order by nvl(update_time,create_time) desc) ranknum
	      	from PBC_PROD_RAISING_SUB_HIS



	                    select #{item.pbcProdId,jdbcType=CHAR},
	                    #{item.raisingDate,jdbcType=CHAR}
	                    from sysibm.SYSDUMMY1



	      )
	      where ranknum = 1
    )
